/**
 * Seat advice for common situations, drawn on a generic 30-row single-aisle cabin
 * (A320 / 737 class). Advice is hand-checked and cites SEAT_SOURCES; nothing here
 * is generated by AI.
 */

export const SEAT_SOURCES = {
  ntsb: {
    name: "NTSB — Preventing Turbulence-Related Injuries (SS-21/01, 2021)",
    url: "https://www.ntsb.gov/safety/safety-studies/Documents/SS2101.pdf",
  },
  faaTurbulence: { name: "FAA — Turbulence: Staying Safe", url: "https://www.faa.gov/travelers/fly_safe/turbulence" },
  greenwich: {
    name: "University of Greenwich for the UK CAA (2008), via The Guardian",
    url: "https://www.theguardian.com/business/2008/jun/26/theairlineindustry.travelnews",
  },
  easaExits: { name: "EASA — Seats by exits", url: "https://www.easa.europa.eu/en/faq/111051" },
  easaChildren: { name: "EASA — Flying with children", url: "https://www.easa.europa.eu/en/light/topics/flying-children-0" },
  euRights: {
    name: "Your Europe — Reduced mobility",
    url: "https://europa.eu/youreurope/citizens/travel/passenger-rights/reduced-mobility/index_en.htm",
  },
} as const;
export type SeatSourceId = keyof typeof SEAT_SOURCES;

export const ROWS = 30;
/** Typical exits: front door, the two over-wing rows and the rear door. */
export const EXIT_ROWS = [1, 12, 13, 30] as const;
/** Rows that sit over the wing box (the aircraft's centre of gravity). */
export const WING_ROWS: [number, number] = [9, 17];

export type Column = "window" | "middle" | "aisle";
export type Situation =
  | "child"
  | "turbulence"
  | "fear"
  | "motion"
  | "legroom"
  | "quickExit"
  | "sleep"
  | "mobility";

export interface SeatAdvice {
  situation: Situation;
  /** Inclusive row ranges to aim for. */
  rows: [number, number][];
  /** Inclusive row ranges to avoid. */
  avoid: [number, number][];
  columns: Column[];
  /** Number of tips under airportGuide-style locale keys seats.tip.<situation>.<n>. */
  tips: number;
  sources: SeatSourceId[];
}

export const SITUATIONS: SeatAdvice[] = [
  { situation: "child", rows: [[5, 11], [14, 17]], avoid: [[12, 13], [26, 30]], columns: ["window", "middle"], tips: 3, sources: ["easaChildren", "easaExits", "ntsb"] },
  { situation: "turbulence", rows: [[9, 11], [14, 17]], avoid: [[25, 30]], columns: ["window", "middle", "aisle"], tips: 2, sources: ["ntsb", "faaTurbulence"] },
  { situation: "fear", rows: [[9, 11], [14, 17]], avoid: [[25, 30]], columns: ["aisle"], tips: 3, sources: ["ntsb"] },
  { situation: "motion", rows: [[9, 11], [14, 17]], avoid: [[25, 30]], columns: ["window"], tips: 2, sources: ["ntsb"] },
  { situation: "legroom", rows: [[1, 1], [12, 13]], avoid: [], columns: ["window", "middle", "aisle"], tips: 2, sources: ["easaExits"] },
  { situation: "quickExit", rows: [[1, 5]], avoid: [[25, 30]], columns: ["aisle"], tips: 2, sources: ["greenwich"] },
  { situation: "sleep", rows: [[4, 11], [14, 20]], avoid: [[1, 2], [28, 30]], columns: ["window"], tips: 2, sources: [] },
  { situation: "mobility", rows: [[2, 6]], avoid: [[12, 13]], columns: ["aisle"], tips: 2, sources: ["euRights", "easaExits"] },
];

export const adviceFor = (s: Situation) => SITUATIONS.find((a) => a.situation === s)!;

/** Children on the booking → start on the child advice; otherwise on the smoothest ride. */
export const defaultSituation = (input: { children: boolean }): Situation => (input.children ? "child" : "turbulence");

export const inRanges = (row: number, ranges: [number, number][]) => ranges.some(([a, b]) => row >= a && row <= b);
